PAIRS = [
 ('Nene Inui','Tsubasa Maki','They met delivering costumes to a playhouse. Their footrace arguments continue long after either has forgotten the original wager.'),
 ('Kenta Ishizaki','Daichi Kawanobe','They exchange metalwork advice and sometimes share a meal after repairs. Both find it easier to discuss a broken fitting than a difficult family conversation.'),
 ('Riko Narumi','Kojirō Tsunematsu','They have referred private pupils to one another. Their arguments about teaching methods conceal a real disagreement over who deserves an education.'),
 ('Haruto Otsuki','Ema Tsukishiro','He supplies precise fittings for some of her instruments. She values his workmanship and has firmly refused his attempts to inspect her private workshop uninvited.'),
 ('Ayato Nikaidō','Haruna Yashima','She once guarded a traveling show in which he performed. They still exchange expensive-looking sweets and complaints about each other’s judgment.'),
 ('Takeshi Onizuka','Reina Hazakura','They know one another from older competition circuits and occasionally share an orchard meal. She has heard his evasive version of the quarrel with his former traveling partner and does not mistake it for the full truth.'),
]

def repair_public_prose(npcs):
 """Repair the supporting-card template without rewriting character data."""
 before=copy.deepcopy(npcs)
 for row in SUPPORT:
  name,role,life=row[0],row[8],row[9];n=npcs[name]
  female=n['gender']=='female';sub='She' if female else 'He';poss='her' if female else 'his'
  public_role='courier' if name=='Koharu Mikazuki' else role
  article='an' if public_role[0].lower() in 'aeiou' else 'a'
  n['basicInfo']=n['basicInfo'].replace(f'{sub} works as {life}.',f'{sub} works as {article} {public_role}.')
  n['abilities']=[s.replace('. '+poss+' ','. '+poss.capitalize()+' ').replace('; they defend an escape route and seek help rather than pretending '+poss+' occupation grants overwhelming combat power.','; '+sub.lower()+' defends an escape route and seeks help when outmatched.') for s in n['abilities']]
 for n in npcs.values():
  for field in ['basicInfo','visualDescription']:
   if field in n:n[field]=re.sub(r'\b([a-z-]+) with vertical slit pupils eyes\b',r'\1 eyes with vertical slit pupils',n[field])
 return {name:[f for f in n if n[f]!=before[name].get(f)] for name,n in npcs.items() if n!=before[name]}

def apply(world,incoming):
 before=copy.deepcopy(world['npcs']);world['npcs']=copy.deepcopy(incoming)
 assert set(before)==set(incoming),'Roster membership changed; review the merge first.'
 relations={}
 for a,b,fact in PAIRS:
  relations[a]=f'{b}: {fact}';relations[b]=f'{a}: {fact}'
 for i,row in enumerate(FIGHTERS+SUPPORT):
  name=row[0];n=world['npcs'][name];female=n['gender']=='female';sub='She' if female else 'He';poss='her' if female else 'his'
  if i<32:_,age,species,level,primary,hair,eyes,weapon,life,flaw,motive,quirk,method=row
  else:
   _,age,species,level,primary,hair,eyes,weapon,role,life,flaw,motive,quirk=row
   method=n['abilities'][0].split(':** ',1)[1].replace('..','.').replace('their ',poss+' ').replace('Their ',sub+' ')
  pressure,voice,courtship,jealousy,secret,point=TEXT[name]
  visual=n['visualDescription'];old=f'with {hair} hair and {eyes} eyes.'
  color,_,style=hair.partition(', ')
  visual=visual.replace(old,f'with {color} hair'+(f', {style},' if style else '')+f' and {eyes} eyes.')
  visual=visual.replace('Their practical',poss.capitalize()+' practical')
  if name=='Genta Shishido':visual=visual.replace('swept or curled horns','swept horns').replace('scaled cheekbones','russet-scaled cheekbones')
  n['visualDescription']=visual
  profile=n['basicInfo'].split('\n- **Gender:**',1)[-1]
  public_role='courier' if name=='Koharu Mikazuki' else (role if i>=32 else '')
  article='an' if public_role[:1].lower() in ['a','e','i','o','u'] else 'a'
  n['basicInfo']=f'{name} {life}. '+(f'{sub} competes at the Crucible alongside {poss} ordinary work.' if i<32 else f'{sub} works as {article} {public_role}.')+'\n\n'+visual+f'\n\n**Equipment:** {sub} normally carries {weapon}, a small purse and '+('a compact work kit.' if i<32 else 'the tools needed for the day’s work.')+'\n\n- **Gender:**'+profile
  unnameds={
   'Kōta Mibu':'His aunt relies on his help at the tile counter; he has not explained how seriously he is considering an apprenticeship elsewhere.',
   'Daisuke Kariya':'He visits his father for weekly cards and has an uncomfortable unfinished apology to a newer dockworker.',
   'Daichi Kawanobe':'His spouse wants time together rather than another promise to take a holiday once work settles down.',
   'Genta Shishido':'His spouse shares the goat-keeping; junior mine workers have learned how quickly his courtesy disappears when a tally is challenged.',
   'Nozomi Hayase':'She lives with her partner and their rescue dogs. The arena physician is a valued colleague, though extra shifts still strain the infirmary.',
  }
  relationship=relations.get(name,unnameds.get(name,f'{sub} has regular dealings with '+('the people connected to '+poss+' everyday work' if i<32 else 'customers and coworkers')+', but keeps much of '+poss+' private life separate from the arena.'))
  # A small number of crime/job connections remain useful and reciprocal.
  if name=='Mika Koshimizu':relationship='Renjirō Suda brings private repair referrals; she dislikes his evasive provenance stories but has accepted the work.'
  if name=='Renjirō Suda':relationship='Mika Koshimizu accepts some of his private repair referrals. He knows that her fear of an inspection makes her easier to pressure.'
  if name=='Shiori Takase':relationship='Koharu Mikazuki handles occasional discreet deliveries. They cooperate for profit and each checks the other’s count.'
  if name=='Koharu Mikazuki':relationship='Shiori Takase buys some discreet consignments. Their trust ends at the agreed goods, price and delivery.'
  knowledge=(f'{sub} admits '+('very little of this to customers' if name in ['Shun Kurebayashi','Yae Mitsuhara','Haruto Otsuki','Renjirō Suda','Momo Shiratori','Shiori Takase','Genta Shishido','Koharu Mikazuki','Mika Koshimizu'] else 'only fragments of this in ordinary conversation')+'. People directly involved know their own part; a familiar face does not know the whole story.')
  n['hiddenInfo']=f'**Private motive:** {motive.capitalize()}.\n\n**What they conceal:** {secret}\n\n**Concealment and knowledge:** {knowledge}\n\n**Pressure point:** {point}\n\n**Relationships:** {relationship}\n\n**How it surfaces:** {sub} {quirk}. A conversation about {poss} actual work or the consequences of a recent choice can reveal more than a direct request for a confession.'
  n['personality']=[f'**Core:** {motive.capitalize()}.',f'**Default behavior:** {sub} {life}. {sub} {flaw}.',f'**Under Pressure:** {pressure}',f'**Speaking Style:** {voice}',f'**Courtship Style:** {courtship}',f'**Jealousy Style:** {jealousy}',f'**Routine or Quirk:** {quirk.capitalize()}.']
  n['abilities']=[f'**Preferred Method:** {method[0].upper()+method[1:].rstrip(".")}.',f'**{primary} Practice:** {sub} uses learned {primary.lower()} workings suited to '+('the range and openings of this fighting method.' if i<32 else poss+' actual work and training.'),f'**Fighting Style:** '+(f'{sub} {method[0].lower()+method[1:].rstrip(".")}. In regulated bouts, the stopping signal ends the exchange.' if i<32 else f'{sub} uses the available technique to protect a route, escape or call for help; prolonged combat is not the aim.')]
 repair_public_prose(world['npcs'])
 # Preserve every user portrait, stat, address, type, identity and affinity exactly.
 for name,n in world['npcs'].items():
  old=incoming[name]
  for field in set(old)|set(n):
   if field not in {'basicInfo','hiddenInfo','personality','abilities','visualDescription'} or name not in TEXT:
    assert n.get(field)==old.get(field),(name,field)
 return {'rewritten':list(TEXT),'namedRelationshipPairs':[(a,b) for a,b,_ in PAIRS], 'userPortraitUrlsPreserved':True}
